from pathlib import Path
import json, math

TMP=Path(__file__).parent

def game_data():
    d=json.loads((TMP/'v5_game_data.json').read_text(encoding='utf-8'))
    assert len(d['zones'])==7 and len(d['cards'])==48 and sum(z['hours'] for z in d['zones'])==552
    assert all(len(z['tests'])==3 for z in d['zones'])
    return d

def zone_for(code):
    return next((z for z in game_data()['zones'] if code in z['modules']),None)

def card_key(code):return 'cards_'+str(((int(code)-1)//4)*4+1)

def refs(b,a,codes):
    return ' · '.join(b.bookmark_link(a['anchor'](c),'Модуль '+c+' / ') for c in codes)

def reading(b,a,code):
    m=next(m for m in a['MODULES'] if m['code']==code)
    l=m['lessons'][0]
    b.p('Видео: '+a['link'](l['video'])+'<br/>Документация: '+a['link'](l['doc']),9.1,markup=True,space=8)

def add_merge_intro(b,a):
    d=game_data(); CW=a['CW'];M=a['MARGIN'];T=a['TEAL'];P=a['PALE'];N=a['NAVY'];U=a['MUTED'];e=a['e'];para=a['para']
    b.new('Единая версия: карта изменений','Объединение планов','merge_v5')
    b.p('Объединены наш универсальный v4 на 130 страниц и присланный игровой v4 на 53 страницы. Здесь одна нумерация модулей, один календарь и единые критерии. Ранние версии уже входят в основу.',10.7,space=13)
    b.table([['Из нашего v4','Из игрового v4'],['36 модулей: база, 24 основных, углубления','7 зон, 7 итоговых испытаний и достижения'],['168 занятий с видео и документацией','46 вопросов сохранены по смыслу и уточнены; ещё 2 добавлены для раздельных интеграций'],['35 недель, часы, резерв и реальный пилот','Наглядные схемы потока, доверия, outbox и каналов'],['Метрики, стоимость, интервью и трекеры','Более конкретные упражнения, карточки повторения и разбор запроса заказчика']],[CW*.50,CW*.50],size=10,pad=7)
    b.callout('Объём не складывается дважды','474 часа исходного игрового плана и 552 часа нашего - оценки пересекающейся программы. В итоговой версии основной маршрут остаётся 552 ч + 138 ч резерва. Испытания, повторение и достижения используют уже запланированную практику.')
    b.section('Порядок сохранён по зависимостям','Discovery - модуль 01. Данные и провайдер - 05 до реальных клиентских документов. Агент, надёжность и диалог - до n8n и расширения интеграций. Пилот идёт в неделях 32-35, параллельное оформление портфолио учитывается отдельно.')
    b.section('Что уточнено технически','КПП, OData, границы гарантий очереди и внешней записи, оценка handoff, исходные значения НДС и жизненный цикл данных. У схем теперь явно обозначены предпосылки и ограничения; подробности - в соответствующих модулях.')
    for key,title in [('level_map','Сопоставление всех 23 уровней'),('game_rules','Правила и учебный прогресс'),('zone_map','Карта семи зон'),('bosses_1','21 контрольное испытание'),('cards_1','48 вопросов с опорными ответами'),('atlas_trust','Дополнительные схемы'),('client_replies','Обсуждение запроса заказчика')]:
        b.p(b.bookmark_link(key,title+' / '),9.6,markup=True,space=4)

    b.new('Все уровни сведены к одной программе','Таблица соответствия','level_map')
    rows=[['В присланном игровом плане','Модуль здесь']]
    names=['Бизнес-задача, архитектура, backend','Очередь, CI, стенд','ML-baseline','Устройство LLM и API','JSON, валидация и tools','Первая CRM и полный сценарий','Первый RAG','Поиск и vector DB','Evals','Данные и провайдер','OCR и документы','n8n','Агенты и workflow','Надёжность и outbox','1С и МойСклад','Наблюдение и стоимость','Безопасность и удаление','Диалог, каналы, оператор','Выпуск и восстановление','Discovery, оценка, scope','Архитектура и команда','Пилот','Портфолио и интервью']
    targets=['01, 02','03','04','06','07','08','09','10','11','05','12','16','13','14','17, 18','20','19','15','21','01, 22','22','23','24']
    for i,(name,target) in enumerate(zip(names,targets),1):rows.append([f'{i:02d}. {name}',target])
    b.table(rows,[CW*.77,CW*.23],size=9.2,pad=4)
    b.p('База A-D соответствует Б1-Б4. Все дополнительные технологии сохранены в Д1-Д8. Два источника истины для часов не ведутся: используйте таблицу объёма и недельный календарь этой версии.',9.5,color=U)
    b.p('Ссылки одинаковой темы объединены вокруг карточки занятия. Дополнительно проверенные материалы N01-N16 находятся в общем реестре. Видеостраницы и тематика проверены; ролики целиком не просматривались.',9.2,color=U)

    b.new('Игровой способ проходить план','Правила без лишних часов','game_rules')
    b.flow(['Задача','Практика + проверка','Артефакт + объяснение','Зачёт и следующий шаг'],'Зона - группа модулей. «Босс» - итоговое испытание зоны. Номер модуля не равен номеру недели.')
    b.section('Как начисляются XP','Модуль закрывается после готового результата, проверки существенного отказа и объяснения. Его награда фиксирована: плановые часы × 10 XP. Основной маршрут даёт 5520 XP. Фактически потраченное время, просмотр, повтор и резерв не увеличивают награду.')
    b.section('Что означает прогресс','Отмечай: не начато / в работе / проверено / требуется повтор. Достижение открывается по доказательству. Испытание ссылается на уже сделанный тест или журнал; отдельные бонусные часы и XP за тот же результат не начисляются.')
    b.table([['Учебный ранг','Порог'],['Старт','0 XP'],['Рабочий стенд','640 XP и испытание зоны 1'],['Первая интеграция','1720 XP и испытание зоны 3'],['Измеряемая система','2440 XP и испытание зоны 4'],['Готовность к пилоту','4760 XP и испытание зоны 6'],['Защищённый проект','5520 XP и испытание зоны 7']],[CW*.64,CW*.36],size=9.7)
    b.p('Это названия учебных этапов. Они не присваивают профессиональный грейд и не заменяют опыт, который требуется в вакансии. Подготовка и углубления отмечаются отдельно от основной шкалы.',9.4,color=U,space=12)
    b.section('Повторение без тупика','Сначала ответь по памяти, затем сверься с опорой и своим кодом. Назови пробел и назначь повтор. Продолжать независимую работу можно; зависимая часть ждёт исправления. Если вопрос требует практики, одной заученной фразы недостаточно.')
    b.section('Ритм и серия занятий','День засчитывается за проверяемый шаг сессии: исправление, измерение или объяснение с примером. Длинное занятие можно разделить. Короткие повторения входят во время объяснения и журнала; доработка пробела использует резерв.')

    b.new('Карта семи зон','Один путь и семь проверок','zone_map')
    b.p('Нажми номер модуля, чтобы открыть занятия и материалы. Часы зон - только основная работа; календарь включает резерв. Испытания проходят внутри указанных недель.',9.6,color=U,space=13)
    colors=['#236090','#167c76','#b77418','#705899','#a25757','#208292','#916280']
    for z,col in zip(d['zones'],colors):
        y=b.y;hh=68;c=b.c;c.setFillColor(P);c.roundRect(M,y-hh,CW,hh,6,fill=1,stroke=0)
        c.setFillColor(a['HexColor'](col));c.roundRect(M,y-hh,5,hh,2,fill=1,stroke=0)
        p=para(f'{z["id"]:02d}. {z["title"]}',10.8,True,N);_,ph=p.wrap(CW-23,100);p.drawOn(c,M+13,y-10-ph)
        mods=' · '.join(f'<a href="#{a["anchor"](m)}" color="{col}"><b>{m}</b></a>' for m in z['modules'])
        p=para(mods+f'  |  {z["hours"]} ч / {z["hours"]*10} XP  |  проверка: неделя {z["week"]}',9.2,markup=True);_,ph=p.wrap(CW-25,100);p.drawOn(c,M+13,y-29-ph)
        p=para('Испытание: '+z['boss'],9.2,color=U);_,ph=p.wrap(CW-25,100);p.drawOn(c,M+13,y-47-ph)
        b.y-=hh+9
    b.figures+=1
    b.p('Итог: 552 часа занятий + 138 часов резерва = 690 часов. Основной календарь: 35 недель при 20 ч/неделю; диагностика и нужная база до старта.',9.6,True,color=T,space=8)
    b.p(b.bookmark_link('execution_weeks_1','Календарь выполнения / '),9.6,markup=True)

    for start in [0,2,4,6]:
        chunk=d['zones'][start:start+2]
        b.new('Контрольные испытания: '+', '.join(str(z['id']) for z in chunk),'Боссы зон',f'bosses_{start+1}')
        b.p('Испытывай отказы на учебном стенде. Для каждого сценария сохрани вход, точку сбоя, ожидаемый и фактический результат, версию и ссылку на доказательство.',9.5,color=U,space=12)
        for z in chunk:
            b.p(f'Зона {z["id"]}. {z["boss"]}',13,True,color=N,space=6)
            b.p(refs(b,a,z['modules'])+f'  |  проверка на неделе {z["week"]}',8.6,markup=True,space=8)
            for j,test in enumerate(z['tests'],1):b.p(f'{j}. {test}',9.7,space=6)
            b.p('<b>Доказательство:</b> '+e(z['evidence']),9.4,markup=True,space=9)
            reading(b,a,z['modules'][0])
            b.y-=4
        if start==6:
            b.table([['Часть защиты','Минуты','Что показать'],['Задача и критерии','5','Процесс, данные, границы, исходное измерение'],['Архитектура и выбор','8','C4, ADR, цена альтернатив'],['Работа и отказ','7','Один путь и восстановление существенного сбоя'],['Результат пилота','5','Качество, стоимость, ограничения, решение'],['Вопросы','5','Личный вклад и следующий шаг']],[CW*.30,CW*.14,CW*.56],size=9.4,pad=5)
        b.callout('Если испытание не прошло','Закрой конкретный дефект, повтори затронутые проверки и запиши результат. Если нет нужного контура или участника, оставь пункт незавершённым; учебная имитация имеет отдельную отметку. Новый срок считается по оставшейся работе.')

    b.new('Достижения за проверенный результат','Мотивация и доказательства','achievements')
    b.p('Отметку ставь после результата и объяснения. Дата и ссылка на код, отчёт или review важнее количества баллов.',10,space=12)
    rows=[['Достижение','Модуль','Как подтвердить']]
    for x in d['achievements']:rows.append([x['title'],x['module'],x['evidence']])
    b.table(rows,[CW*.27,CW*.12,CW*.61],size=9.3,pad=5)
    b.label('Мои следующие три достижения')
    for n in range(1,4):b.p(f'{n}. ____________________  Дата: __________  Доказательство: __________________',9.4,space=3)
    b.p('Для итогового достижения «Семь испытаний» приложи семь протоколов. Если часть выполнена с mock или как репетиция, этот статус остаётся видимым.',9.3,color=U)

def add_cards(b,a):
    d=game_data();CW=a['CW'];U=a['MUTED'];T=a['TEAL'];N=a['NAVY'];e=a['e']
    cards=sorted(d['cards'],key=lambda x:(int(x['module']),x['id']))
    for start in range(0,24,4):
        b.new(f'Колода: модули {start+1:02d}-{start+4:02d}','48 вопросов и опорные ответы',f'cards_{start+1}')
        b.p('Закрой строку «Опора», ответь вслух и покажи пример из проекта. Затем проверь ответ. После первого зачёта ориентир повторов: через 1, 3 и 6 недель; даты подстрой по ошибкам.',9.4,color=U,space=10)
        for n in range(start+1,start+5):
            code=f'{n:02d}';these=[x for x in cards if x['module']==code];assert len(these)==2
            b.p(b.bookmark_link(a['anchor'](code),'Модуль '+code+' и материалы / '),10.1,True,markup=True,space=6)
            for card in these:
                b.p(f'{card["id"]}. {card["question"]}',9.9,True,color=N,space=3)
                b.p('Опора: '+card['cue'],9.2,color=U,leading=12.1,space=5)
            b.p('Первый зачёт: ________  Повторы: ________ / ________ / ________  Пробел: __________',8.3,color=T,space=12)
        b.p('Короткий повтор входит в существующее время журнала и объяснения. Повторы поздних модулей продолжаются после недели 35; это поддержание навыка, без повторного начисления XP.',9.1,color=U,space=0)

def add_client_page(b,a):
    CW=a['CW'];N=a['NAVY'];U=a['MUTED']
    b.new('Три запроса заказчика: рабочий ответ','Практика модулей 01 и 22','client_replies')
    b.p('Учебные черновики для тренировки разговора. Подставь свой процесс, измерения и ограничения; письма никому не отправляются автоматически.',10,color=U,space=12)
    examples=[
      ('«Нужен бот для всего»','Предлагаю начать с одного процесса: менеджер получает ответ по разрешённым регламентам и видит источник. До оценки уточним типовые вопросы, доступы, объём и цену ошибки. На пилоте сравним время решения и качество; после него выберем следующий сценарий.'),
      ('«Сразу сделаем fine-tuning»','Сначала зафиксируем проблему: не хватает знаний, модель не соблюдает формат или ошибается на устойчивом типе задачи. Сравним текущий вариант, промпт, retrieval и дообучение там, где для него есть гипотеза и данные. Выбор примем по качеству, цене и регрессиям на одном наборе.'),
      ('«Пусть всё работает без человека»','Определим допустимые действия и цену ошибки. Для начала система подготовит проверяемое предложение, сотрудник подтвердит конкретную версию. Автоматизацию расширим для согласованных сценариев после наблюдения качества; оставим понятный путь отмены, остановки и передачи оператору.')]
    for title,body in examples:b.section(title,body)
    b.section('Упражнение','Перепиши три ответа для продаж, бухгалтерии или склада. В каждом укажи проблему, один следующий шаг, что нужно от клиента и как будет принято решение. Не обещай цену или срок без перечня работ и допущений.')
    b.table([['15 минут для человека вне IT','Результат разговора'],['3 мин: текущий процесс','Собеседник узнаёт свою задачу'],['5 мин: предлагаемый первый шаг','Понятны данные, действие и роль человека'],['4 мин: срок, стоимость и ограничения','Диапазон и неизвестные явно названы'],['3 мин: вопросы и решение','Владелец и следующий шаг зафиксированы']],[CW*.49,CW*.51],size=9.5,pad=5)
    reading(b,a,'22')
